//! Parity tests for the model-free parts of
//! `gpt_sovits_text::tts_infer_pack::text_preprocessor` against fixtures
//! generated by `parity/text_preprocessor/gen_fixtures.py`:
//! `get_first`, `merge_short_text_in_array`,
//! `replace_consecutive_punctuation`, `filter_text` and `pre_seg_text`.
//! `get_phones_and_bert` and `preprocess` are checked by `tests/e2e.rs`.
//! There are no known mismatches.

#[path = "common/e2e_common.rs"]
mod e2e_common;

use std::collections::BTreeMap;

use e2e_common::{FakeBert, bare_text_preprocessor, lines, resolve_methods};
use gpt_sovits_text::TextPreprocessor;
use gpt_sovits_text::tts_infer_pack::text_preprocessor::{
  Error, get_first, merge_short_text_in_array,
};
use serde_json::{Value, json};

fn strings(v: &Value) -> Vec<String> {
  v.as_array()
    .unwrap()
    .iter()
    .map(|s| s.as_str().unwrap().to_string())
    .collect()
}

fn encode(r: Result<Vec<String>, Error>) -> Value {
  match r {
    Ok(v) => json!(v),
    Err(e) => json!({"error": e.name()}),
  }
}

#[test]
fn functions_match_python() {
  let tp: TextPreprocessor<FakeBert> = bare_text_preprocessor();
  let mut stats: BTreeMap<String, (usize, usize)> = BTreeMap::new();
  let mut failures = Vec::new();
  let mut check = |name: String, text: &str, want: &Value, got: Value| {
    let e = stats.entry(name.clone()).or_default();
    e.0 += 1;
    if &got == want {
      e.1 += 1;
    } else {
      failures.push(format!("{name}({text:?})\n  want {want}\n  got  {got}"));
    }
  };
  for rec in lines(include_str!("fixtures/text_preprocessor/functions.jsonl")) {
    let text = rec["text"].as_str().unwrap();
    check(
      "get_first".into(),
      text,
      &rec["get_first"],
      json!(get_first(text)),
    );
    check(
      "replace_consecutive_punctuation".into(),
      text,
      &rec["replace_consecutive_punctuation"],
      json!(tp.replace_consecutive_punctuation(text)),
    );
    let pieces: Vec<String> = text.split('\n').map(str::to_string).collect();
    check(
      "filter_text".into(),
      text,
      &rec["filter_text"],
      encode(tp.filter_text(pieces)),
    );
    for (lang, outs) in rec["pre_seg_text"].as_object().unwrap() {
      for (method, want) in resolve_methods(outs) {
        let got = encode(tp.pre_seg_text(text, lang, &method));
        check(format!("pre_seg_text {lang} {method}"), text, &want, got);
      }
    }
  }
  for (name, (n, ok)) in &stats {
    eprintln!("{name}: {ok}/{n}");
  }
  assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn merge_short_text_in_array_matches_python() {
  let mut n = 0;
  for rec in lines(include_str!(
    "fixtures/text_preprocessor/merge_short_text_in_array.jsonl"
  )) {
    let texts = strings(&rec["texts"]);
    let threshold = rec["threshold"].as_u64().unwrap() as usize;
    let got = merge_short_text_in_array(texts.clone(), threshold);
    assert_eq!(
      got,
      strings(&rec["out"]),
      "merge_short_text_in_array({texts:?}, {threshold})"
    );
    n += 1;
  }
  assert_eq!(n, 600);
}
